#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    char *s;
    int pos;
    int len;
} Parser;

static void skip_separators(Parser *p) {
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == ',' || c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static char *next_token(Parser *p) {
    skip_separators(p);
    if (p->pos >= p->len) return NULL;

    int start = p->pos;
    if (p->s[p->pos] == '[') {
        int depth = 0;
        do {
            char c = p->s[p->pos++];
            if (c == '[') depth++;
            else if (c == ']') depth--;
        } while (p->pos < p->len && depth > 0);
    } else {
        while (p->pos < p->len &&
               p->s[p->pos] != ',' &&
               p->s[p->pos] != ']') {
            p->pos++;
        }
    }

    int n = p->pos - start;
    char *token = (char *)malloc((size_t)n + 1);
    memcpy(token, p->s + start, (size_t)n);
    token[n] = '\0';
    return token;
}

static int parse_int(Parser *p) {
    char *tok = next_token(p);
    int value = atoi(tok);
    free(tok);
    return value;
}

static int **parse_pairs(Parser *p, int *rows) {
    char *outer = next_token(p);
    if (strcmp(outer, "[]") == 0) {
        free(outer);
        *rows = 0;
        return NULL;
    }

    int len = (int)strlen(outer);
    char *inner = (char *)malloc((size_t)len - 1);
    memcpy(inner, outer + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(outer);

    int count = 0, depth = 0;
    for (int i = 0; inner[i]; ++i) {
        if (inner[i] == '[') {
            if (depth == 0) count++;
            depth++;
        } else if (inner[i] == ']') {
            depth--;
        }
    }

    int **pairs = (int **)malloc((size_t)count * sizeof(int *));
    Parser q = {inner, 0, (int)strlen(inner)};

    for (int i = 0; i < count; ++i) {
        char *row = next_token(&q);
        int row_len = (int)strlen(row);
        Parser r = {row + 1, 0, row_len - 2};
        pairs[i] = (int *)malloc(2 * sizeof(int));
        pairs[i][0] = parse_int(&r);
        pairs[i][1] = parse_int(&r);
        free(row);
    }

    free(inner);
    *rows = count;
    return pairs;
}

bool canFinish(int numCourses, int **prerequisites, int prerequisitesSize, int *prerequisitesColSize) {
    (void)prerequisitesColSize;

    int *indegree = (int *)calloc((size_t)numCourses, sizeof(int));
    int *head = (int *)malloc((size_t)numCourses * sizeof(int));
    int *to = (int *)malloc((size_t)prerequisitesSize * sizeof(int));
    int *next = (int *)malloc((size_t)prerequisitesSize * sizeof(int));

    for (int i = 0; i < numCourses; ++i) head[i] = -1;

    for (int i = 0; i < prerequisitesSize; ++i) {
        int course = prerequisites[i][0];
        int prerequisite = prerequisites[i][1];
        to[i] = course;
        next[i] = head[prerequisite];
        head[prerequisite] = i;
        indegree[course]++;
    }

    int *queue = (int *)malloc((size_t)numCourses * sizeof(int));
    int front = 0, back = 0, completed = 0;

    for (int i = 0; i < numCourses; ++i) {
        if (indegree[i] == 0) queue[back++] = i;
    }

    while (front < back) {
        int course = queue[front++];
        completed++;

        for (int edge = head[course]; edge != -1; edge = next[edge]) {
            int nxt = to[edge];
            if (--indegree[nxt] == 0) queue[back++] = nxt;
        }
    }

    free(indegree);
    free(head);
    free(to);
    free(next);
    free(queue);

    return completed == numCourses;
}

int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    size_t len = strlen(line);
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        line[--len] = '\0';
    }

    if (len < 2) return 0;

    char *raw = (char *)malloc(len - 1);
    memcpy(raw, line + 1, len - 2);
    raw[len - 2] = '\0';

    Parser p = {raw, 0, (int)strlen(raw)};
    int numCourses = parse_int(&p);
    int prerequisitesSize = 0;
    int **prerequisites = parse_pairs(&p, &prerequisitesSize);

    int *colSizes = NULL;
    if (prerequisitesSize > 0) {
        colSizes = (int *)malloc((size_t)prerequisitesSize * sizeof(int));
        for (int i = 0; i < prerequisitesSize; ++i) colSizes[i] = 2;
    }

    bool result = canFinish(numCourses, prerequisites, prerequisitesSize, colSizes);
    printf("%s\n", result ? "true" : "false");

    for (int i = 0; i < prerequisitesSize; ++i) free(prerequisites[i]);
    free(prerequisites);
    free(colSizes);
    free(raw);
    return 0;
}

