class Solution {
public:
    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
        vector<vector<int>> graph(numCourses);
        vector<int> indegree(numCourses, 0);

        for (const auto& edge : prerequisites) {
            int course = edge[0], prerequisite = edge[1];
            graph[prerequisite].push_back(course);
            ++indegree[course];
        }

        queue<int> q;
        for (int i = 0; i < numCourses; ++i) {
            if (indegree[i] == 0) q.push(i);
        }

        int completed = 0;
        while (!q.empty()) {
            int course = q.front();
            q.pop();
            ++completed;
            for (int next : graph[course]) {
                if (--indegree[next] == 0) q.push(next);
            }
        }
        return completed == numCourses;
    }
};

static vector<string> splitTop(const string& s) {
    string t = s;
    if (t == "[]") return {};
    t = t.substr(1, t.size() - 2);
    vector<string> parts;
    int depth = 0, start = 0;
    for (int i = 0; i < (int)t.size(); ++i) {
        if (t[i] == '[') ++depth;
        else if (t[i] == ']') --depth;
        else if (t[i] == ',' && depth == 0) {
            parts.push_back(t.substr(start, i - start));
            start = i + 1;
        }
    }
    parts.push_back(t.substr(start));
    return parts;
}

static vector<int> toIntVector(const string& s) {
    vector<string> parts = splitTop(s);
    vector<int> result;
    for (const string& p : parts) result.push_back(stoi(p));
    return result;
}

static vector<vector<int>> toInt2D(const string& s) {
    vector<string> rows = splitTop(s);
    vector<vector<int>> result;
    for (const string& row : rows) result.push_back(toIntVector(row));
    return result;
}

int main() {
    string line;
    getline(cin, line);
    string inner = line.substr(1, line.size() - 2);

    size_t comma = inner.find(',');
    int numCourses = stoi(inner.substr(0, comma));
    string prereqText = inner.substr(comma + 1);

    vector<vector<int>> prerequisites = toInt2D(prereqText);
    bool result = Solution().canFinish(numCourses, prerequisites);
    cout << (result ? "true" : "false") << '\n';
    return 0;
}

