import java.io.*;
import java.util.*;

class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<Integer>[] graph = new ArrayList[numCourses];
        for (int i = 0; i < numCourses; i++) graph[i] = new ArrayList<>();

        int[] indegree = new int[numCourses];
        for (int[] edge : prerequisites) {
            int course = edge[0], prerequisite = edge[1];
            graph[prerequisite].add(course);
            indegree[course]++;
        }

        ArrayDeque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) {
            if (indegree[i] == 0) queue.add(i);
        }

        int completed = 0;
        while (!queue.isEmpty()) {
            int course = queue.remove();
            completed++;
            for (int next : graph[course]) {
                if (--indegree[next] == 0) queue.add(next);
            }
        }
        return completed == numCourses;
    }
}

public class Main {
    static String[] splitTop(String s) {
        s = s.trim();
        if (s.equals("[]")) return new String[0];
        s = s.substring(1, s.length() - 1);
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        parts.add(s.substring(start).trim());
        return parts.toArray(new String[0]);
    }

    static int[] toIntArray(String s) {
        String[] parts = splitTop(s);
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) result[i] = Integer.parseInt(parts[i].trim());
        return result;
    }

    static int[][] toInt2D(String s) {
        String[] rows = splitTop(s);
        int[][] result = new int[rows.length][];
        for (int i = 0; i < rows.length; i++) result[i] = toIntArray(rows[i]);
        return result;
    }

    static String nextToken(String s, int[] pos) {
        while (pos[0] < s.length() && (s.charAt(pos[0]) == ',' || Character.isWhitespace(s.charAt(pos[0])))) pos[0]++;
        int start = pos[0];
        if (s.charAt(pos[0]) == '[') {
            int depth = 0;
            while (pos[0] < s.length()) {
                char c = s.charAt(pos[0]++);
                if (c == '[') depth++;
                else if (c == ']') {
                    depth--;
                    if (depth == 0) break;
                }
            }
        } else {
            while (pos[0] < s.length() && s.charAt(pos[0]) != ',') pos[0]++;
        }
        return s.substring(start, pos[0]).trim();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        String inner = line.substring(1, line.length() - 1);
        int[] pos = {0};
        int numCourses = Integer.parseInt(nextToken(inner, pos));
        int[][] prerequisites = toInt2D(nextToken(inner, pos));
        System.out.println(new Solution().canFinish(numCourses, prerequisites));
    }
}

